SELECT c.arm,count(*) calls,count(DISTINCT c.sessionId) sessions,count(r.tool_use_id) joined_results,count(DISTINCT (c.sessionId,c.tool_use_id)) unique_calls,count(c.timestamp) timestamped_calls FROM calls c LEFT JOIN full_results r USING(harness,sessionId,tool_use_id) GROUP BY c.arm ORDER BY c.arm; SELECT c.arm,m.model,count(*) turns,sum(m.tool_calls) calls,count(*) FILTER(WHERE m.tool_calls>1) multi_call_turns,max(m.tool_calls) max_calls FROM model_turns m JOIN benchmark_cells c USING(sessionId) GROUP BY c.arm,m.model ORDER BY c.arm;
